export const REFILL_TANK_EVM_TX = "import FungibleToken from 0xFungible\nimport FlowToken from 0xFlowToken\nimport EVM from 0xEVM\nimport FlowEVMBridgeConfig from 0xFlowEVMBridge\nimport FlowEVMBridgeUtils from 0xFlowEVMBridge\nimport FlovatarDustToken from 0xFlovatar\nimport FlovatarUniverseBuilder from 0xFUB\nimport SwapRouter from 0xSwapRouter\nimport SwapConfig from 0xSwapConfig\n\n// Refill the design-assistant tank PAYING WITH A TOKEN ON FLOW EVM (e.g. USDC) held by the wallet's EVM account (COA),\n// in ONE transaction. Same TankRefilled + TokensBurned events as a \u0110UST refill.\n//  viaFlow = false (\"EVM pool\"): path = [tokenIn, ..., \u0110UST ERC-20]; the DEX router swaps tokenIn for EXACTLY `amount`\n//    \u0110UST into the COA, the bridge moves that \u0110UST to Cadence, refillTank burns it.\n//  viaFlow = true (\"via FLOW\", no \u0110UST liquidity needed on EVM): path = [tokenIn, ..., WFLOW]; FLOW needed =\n//    Increment getAmountsIn(amount); the router swaps tokenIn for exactly that WFLOW, it is unwrapped and moved to\n//    Cadence, Increment swaps it for exactly `amount` \u0110UST, refillTank burns it; any FLOW left goes to the FLOW vault.\n// Spending cap: the router may take at most maxIn of tokenIn (approval = maxIn, reset to 0 at the end); unused tokenIn\n// never leaves the COA. Reverts (nothing spent) above maxIn (EXCESSIVE_INPUT_AMOUNT) or after `deadline` (EXPIRED).\ntransaction(amount: UFix64, path: [String], maxIn: UInt256, deadline: UInt256, router: String, viaFlow: Bool, ref: String) {\n    let payment: @{FungibleToken.Vault}\n    let account: Address\n    prepare(signer: auth(BorrowValue) &Account) {\n        assert(path.length >= 2, message: \"Invalid swap path\")\n        let coa = signer.storage.borrow<auth(EVM.Call, EVM.Withdraw, EVM.Bridge) &EVM.CadenceOwnedAccount>(from: /storage/evm)\n            ?? panic(\"This wallet has no Flow EVM account\")\n        let flowVault = signer.storage.borrow<auth(FungibleToken.Withdraw) &FlowToken.Vault>(from: /storage/flowTokenVault)\n            ?? panic(\"No FLOW vault\")\n        let zero = EVM.Balance(attoflow: 0)\n        let rt = EVM.addressFromString(router)\n        let evmPath: [EVM.EVMAddress] = []\n        for p in path { evmPath.append(EVM.addressFromString(p)) }\n        let tokenIn = evmPath[0]\n        let last = evmPath[evmPath.length - 1].toString()\n        let flowKey = SwapConfig.SliceTokenTypeIdentifierFromVaultType(vaultTypeIdentifier: Type<@FlowToken.Vault>().identifier)\n        let dustKey = SwapConfig.SliceTokenTypeIdentifierFromVaultType(vaultTypeIdentifier: Type<@FlovatarDustToken.Vault>().identifier)\n\n        var outWei: UInt256 = 0\n        if viaFlow {\n            let wflow = FlowEVMBridgeConfig.getEVMAddressAssociated(with: Type<@FlowToken.Vault>()) ?? panic(\"No WFLOW association\")\n            assert(last == wflow.toString(), message: \"The swap path must end with WFLOW\")\n            let flowNeeded = SwapRouter.getAmountsIn(amountOut: amount, tokenKeyPath: [flowKey, dustKey])[0]\n            outWei = FlowEVMBridgeUtils.ufix64ToUInt256(value: flowNeeded, decimals: 18)\n        } else {\n            let dustEvm = FlowEVMBridgeConfig.getEVMAddressAssociated(with: Type<@FlovatarDustToken.Vault>()) ?? panic(\"\u0110UST is not on the bridge\")\n            assert(last == dustEvm.toString(), message: \"The swap path must end with the bridged \u0110UST\")\n            outWei = FlowEVMBridgeUtils.ufix64ToUInt256(value: amount, decimals: 18)\n        }\n\n        // EVM swap: tokenIn -> exact output, capped at maxIn\n        var r = coa.call(to: tokenIn, data: EVM.encodeABIWithSignature(\"approve(address,uint256)\", [rt, maxIn]), gasLimit: 120_000, value: zero)\n        assert(r.status == EVM.Status.successful, message: \"approve failed\")\n        r = coa.call(\n            to: rt,\n            data: EVM.encodeABIWithSignature(\"swapTokensForExactTokens(uint256,uint256,address[],address,uint256)\", [outWei, maxIn, evmPath, coa.address(), deadline]),\n            gasLimit: 1_500_000, value: zero)\n        if r.status != EVM.Status.successful {\n            // surface the router's revert reason (Error(string), selector 0x08c379a0), e.g. \"...: EXCESSIVE_INPUT_AMOUNT\"\n            var reason = r.errorMessage\n            if r.data.length > 68 && r.data[0] == 8 && r.data[1] == 195 && r.data[2] == 121 && r.data[3] == 160 {\n                reason = EVM.decodeABI(types: [Type<String>()], data: r.data.slice(from: 4, upTo: r.data.length))[0] as! String\n            }\n            panic(\"EVM swap failed: \".concat(reason))\n        }\n        r = coa.call(to: tokenIn, data: EVM.encodeABIWithSignature(\"approve(address,uint256)\", [rt, UInt256(0)]), gasLimit: 120_000, value: zero)\n\n        if viaFlow {\n            r = coa.call(to: evmPath[evmPath.length - 1], data: EVM.encodeABIWithSignature(\"withdraw(uint256)\", [outWei]), gasLimit: 120_000, value: zero)\n            assert(r.status == EVM.Status.successful, message: \"WFLOW unwrap failed\")\n            let flowIn <- coa.withdraw(balance: EVM.Balance(attoflow: UInt(outWei)))\n            let vaults <- SwapRouter.swapTokensForExactTokens(vaultInMax: <-flowIn, exactAmountOut: amount, tokenKeyPath: [flowKey, dustKey],\n                deadline: UFix64(UInt64(deadline)))\n            let leftover <- vaults.removeLast()\n            let swapped <- vaults.removeLast()\n            destroy vaults\n            flowVault.deposit(from: <-leftover)\n            assert(swapped.balance >= amount, message: \"The swap returned less \u0110UST than the refill amount\")\n            self.payment <- swapped.withdraw(amount: amount)\n            if let mine = signer.storage.borrow<&FlovatarDustToken.Vault>(from: FlovatarDustToken.VaultStoragePath) {\n                mine.deposit(from: <-swapped)\n            } else {\n                assert(swapped.balance == 0.0, message: \"No \u0110UST vault for the swap remainder\")\n                destroy swapped\n            }\n        } else {\n            let fee <- flowVault.withdraw(amount: FlowEVMBridgeUtils.calculateBridgeFee(bytes: 0))\n            let bridged <- coa.withdrawTokens(type: Type<@FlovatarDustToken.Vault>(), amount: outWei,\n                feeProvider: &fee as auth(FungibleToken.Withdraw) &{FungibleToken.Provider})\n            flowVault.deposit(from: <-fee)\n            assert(bridged.balance == amount, message: \"The bridge returned a different \u0110UST amount\")\n            self.payment <- bridged\n        }\n        self.account = signer.address\n    }\n    execute {\n        FlovatarUniverseBuilder.refillTank(payment: <-self.payment, account: self.account, ref: ref)\n    }\n}\n";
export const BUY_DUST_EVM_TX = "import FungibleToken from 0xFungible\nimport FlowToken from 0xFlowToken\nimport EVM from 0xEVM\nimport FlowEVMBridgeConfig from 0xFlowEVMBridge\nimport FlowEVMBridgeUtils from 0xFlowEVMBridge\nimport FlovatarDustToken from 0xFlovatar\nimport SwapRouter from 0xSwapRouter\nimport SwapConfig from 0xSwapConfig\n\n// Buy EXACTLY `amount` \u0110UST paying with a token on Flow EVM (e.g. USDC) held by the wallet's EVM account (COA), in ONE\n// transaction; the \u0110UST lands in the wallet's Cadence \u0110UST vault (created when missing). Routes as in refill_tank_evm:\n//  viaFlow = false: path = [tokenIn, ..., \u0110UST ERC-20] on the EVM DEX, then the bridge moves the \u0110UST to Cadence;\n//  viaFlow = true:  path = [tokenIn, ..., WFLOW] on the EVM DEX, unwrap, then Increment FLOW -> exact \u0110UST in Cadence.\n// The router may take at most maxIn of tokenIn (approval reset to 0 afterwards); reverts above maxIn or after deadline.\ntransaction(amount: UFix64, path: [String], maxIn: UInt256, deadline: UInt256, router: String, viaFlow: Bool) {\n    prepare(signer: auth(Storage, Capabilities) &Account) {\n        assert(path.length >= 2, message: \"Invalid swap path\")\n        if signer.storage.borrow<&FlovatarDustToken.Vault>(from: FlovatarDustToken.VaultStoragePath) == nil {\n            signer.storage.save(<-FlovatarDustToken.createEmptyVault(vaultType: Type<@FlovatarDustToken.Vault>()), to: FlovatarDustToken.VaultStoragePath)\n        }\n        if !signer.capabilities.get<&FlovatarDustToken.Vault>(FlovatarDustToken.VaultReceiverPath).check() {\n            signer.capabilities.unpublish(FlovatarDustToken.VaultReceiverPath)\n            signer.capabilities.publish(signer.capabilities.storage.issue<&FlovatarDustToken.Vault>(FlovatarDustToken.VaultStoragePath), at: FlovatarDustToken.VaultReceiverPath)\n        }\n        if !signer.capabilities.get<&FlovatarDustToken.Vault>(FlovatarDustToken.VaultBalancePath).check() {\n            signer.capabilities.unpublish(FlovatarDustToken.VaultBalancePath)\n            signer.capabilities.publish(signer.capabilities.storage.issue<&FlovatarDustToken.Vault>(FlovatarDustToken.VaultStoragePath), at: FlovatarDustToken.VaultBalancePath)\n        }\n        let dustVault = signer.storage.borrow<&FlovatarDustToken.Vault>(from: FlovatarDustToken.VaultStoragePath)!\n        let coa = signer.storage.borrow<auth(EVM.Call, EVM.Withdraw, EVM.Bridge) &EVM.CadenceOwnedAccount>(from: /storage/evm)\n            ?? panic(\"This wallet has no Flow EVM account\")\n        let flowVault = signer.storage.borrow<auth(FungibleToken.Withdraw) &FlowToken.Vault>(from: /storage/flowTokenVault)\n            ?? panic(\"No FLOW vault\")\n        let zero = EVM.Balance(attoflow: 0)\n        let rt = EVM.addressFromString(router)\n        let evmPath: [EVM.EVMAddress] = []\n        for p in path { evmPath.append(EVM.addressFromString(p)) }\n        let tokenIn = evmPath[0]\n        let last = evmPath[evmPath.length - 1].toString()\n        let flowKey = SwapConfig.SliceTokenTypeIdentifierFromVaultType(vaultTypeIdentifier: Type<@FlowToken.Vault>().identifier)\n        let dustKey = SwapConfig.SliceTokenTypeIdentifierFromVaultType(vaultTypeIdentifier: Type<@FlovatarDustToken.Vault>().identifier)\n\n        var outWei: UInt256 = 0\n        if viaFlow {\n            let wflow = FlowEVMBridgeConfig.getEVMAddressAssociated(with: Type<@FlowToken.Vault>()) ?? panic(\"No WFLOW association\")\n            assert(last == wflow.toString(), message: \"The swap path must end with WFLOW\")\n            outWei = FlowEVMBridgeUtils.ufix64ToUInt256(value: SwapRouter.getAmountsIn(amountOut: amount, tokenKeyPath: [flowKey, dustKey])[0], decimals: 18)\n        } else {\n            let dustEvm = FlowEVMBridgeConfig.getEVMAddressAssociated(with: Type<@FlovatarDustToken.Vault>()) ?? panic(\"\u0110UST is not on the bridge\")\n            assert(last == dustEvm.toString(), message: \"The swap path must end with the bridged \u0110UST\")\n            outWei = FlowEVMBridgeUtils.ufix64ToUInt256(value: amount, decimals: 18)\n        }\n        var r = coa.call(to: tokenIn, data: EVM.encodeABIWithSignature(\"approve(address,uint256)\", [rt, maxIn]), gasLimit: 120_000, value: zero)\n        assert(r.status == EVM.Status.successful, message: \"approve failed\")\n        r = coa.call(\n            to: rt,\n            data: EVM.encodeABIWithSignature(\"swapTokensForExactTokens(uint256,uint256,address[],address,uint256)\", [outWei, maxIn, evmPath, coa.address(), deadline]),\n            gasLimit: 1_500_000, value: zero)\n        if r.status != EVM.Status.successful {\n            // surface the router's revert reason (Error(string), selector 0x08c379a0), e.g. \"...: EXCESSIVE_INPUT_AMOUNT\"\n            var reason = r.errorMessage\n            if r.data.length > 68 && r.data[0] == 8 && r.data[1] == 195 && r.data[2] == 121 && r.data[3] == 160 {\n                reason = EVM.decodeABI(types: [Type<String>()], data: r.data.slice(from: 4, upTo: r.data.length))[0] as! String\n            }\n            panic(\"EVM swap failed: \".concat(reason))\n        }\n        r = coa.call(to: tokenIn, data: EVM.encodeABIWithSignature(\"approve(address,uint256)\", [rt, UInt256(0)]), gasLimit: 120_000, value: zero)\n\n        if viaFlow {\n            r = coa.call(to: evmPath[evmPath.length - 1], data: EVM.encodeABIWithSignature(\"withdraw(uint256)\", [outWei]), gasLimit: 120_000, value: zero)\n            assert(r.status == EVM.Status.successful, message: \"WFLOW unwrap failed\")\n            let vaults <- SwapRouter.swapTokensForExactTokens(vaultInMax: <-coa.withdraw(balance: EVM.Balance(attoflow: UInt(outWei))),\n                exactAmountOut: amount, tokenKeyPath: [flowKey, dustKey], deadline: UFix64(UInt64(deadline)))\n            let leftover <- vaults.removeLast()\n            let swapped <- vaults.removeLast()\n            destroy vaults\n            flowVault.deposit(from: <-leftover)\n            assert(swapped.balance >= amount, message: \"The swap returned less \u0110UST than requested\")\n            dustVault.deposit(from: <-swapped)\n        } else {\n            let fee <- flowVault.withdraw(amount: FlowEVMBridgeUtils.calculateBridgeFee(bytes: 0))\n            let bridged <- coa.withdrawTokens(type: Type<@FlovatarDustToken.Vault>(), amount: outWei,\n                feeProvider: &fee as auth(FungibleToken.Withdraw) &{FungibleToken.Provider})\n            flowVault.deposit(from: <-fee)\n            assert(bridged.balance == amount, message: \"The bridge returned a different \u0110UST amount\")\n            dustVault.deposit(from: <-bridged)\n        }\n    }\n}\n";
export const TEST_USDC_FAUCET_TX = "import EVM from 0xEVM\n\n// TESTNET ONLY: get test USDC (FlovatarTestUSDC faucet, max 10,000 per call) into your Flow EVM account (COA).\n// Creates the COA at /storage/evm first when the wallet has none. On the testnet site this also stands in for\n// \"USDC arrived from another chain\" (no cross-chain bridge serves Flow EVM testnet).\ntransaction(usdc: String, amount: UInt256) {\n    prepare(signer: auth(Storage, Capabilities) &Account) {\n        if signer.storage.type(at: /storage/evm) == nil {\n            signer.storage.save(<-EVM.createCadenceOwnedAccount(), to: /storage/evm)\n            signer.capabilities.unpublish(/public/evm)\n            signer.capabilities.publish(signer.capabilities.storage.issue<&EVM.CadenceOwnedAccount>(/storage/evm), at: /public/evm)\n        }\n        let coa = signer.storage.borrow<auth(EVM.Call) &EVM.CadenceOwnedAccount>(from: /storage/evm) ?? panic(\"No COA\")\n        let r = coa.call(to: EVM.addressFromString(usdc), data: EVM.encodeABIWithSignature(\"mint(address,uint256)\", [coa.address(), amount]),\n            gasLimit: 150_000, value: EVM.Balance(attoflow: 0))\n        assert(r.status == EVM.Status.successful, message: \"test USDC faucet failed: \".concat(r.errorMessage))\n    }\n}\n";
export const DUST_EVM_QUOTE_SCRIPT = "import FungibleToken from 0xFungible\nimport FlowToken from 0xFlowToken\nimport EVM from 0xEVM\nimport FlowEVMBridgeConfig from 0xFlowEVMBridge\nimport FlowEVMBridgeUtils from 0xFlowEVMBridge\nimport FlovatarDustToken from 0xFlovatar\nimport SwapRouter from 0xSwapRouter\nimport SwapConfig from 0xSwapConfig\nimport SwapFactory from 0xSwapFactory\nimport SwapInterfaces from 0xSwapConfig\n\n// Quote \"pay with a Flow EVM token\" for EXACTLY `amount` \u0110UST, for every candidate route (read-only, chain-first):\n//   routes[i] = {path: [EVM addr], viaFlow: Bool, ok: Bool, amountIn: UInt256 (tokenIn base units), flowNeeded: UFix64,\n//                hops: [[reserveIn, reserveOut] per hop, base units], error: String}\n// viaFlow routes: FLOW needed from the Increment \u0110UST/FLOW pool, then tokenIn -> WFLOW on the EVM DEX.\n// Also returns the wallet's COA address, its balance of `tokenIn` (= paths[0][0]), spendable FLOW, Cadence \u0110UST balance,\n// the bridged \u0110UST / WFLOW addresses and the Increment reserves.\naccess(all) fun dry(_ to: EVM.EVMAddress, _ sig: String, _ args: [AnyStruct]): EVM.Result {\n    return EVM.dryCall(from: EVM.addressFromString(\"0x0000000000000000000000000000000000000001\"), to: to,\n        data: EVM.encodeABIWithSignature(sig, args), gasLimit: 2_000_000, value: EVM.Balance(attoflow: 0))\n}\n\naccess(all) fun hopReserves(_ factory: EVM.EVMAddress, _ a: EVM.EVMAddress, _ b: EVM.EVMAddress): [UInt256] {\n    let p = dry(factory, \"getPair(address,address)\", [a, b])\n    if p.status != EVM.Status.successful { return [] }\n    let pair = EVM.decodeABI(types: [Type<EVM.EVMAddress>()], data: p.data)[0] as! EVM.EVMAddress\n    if pair.toString() == \"0000000000000000000000000000000000000000\" { return [] }\n    let r = dry(pair, \"getReserves()\", [])\n    let t = dry(pair, \"token0()\", [])\n    if r.status != EVM.Status.successful || t.status != EVM.Status.successful { return [] }\n    let rs = EVM.decodeABI(types: [Type<UInt256>(), Type<UInt256>(), Type<UInt256>()], data: r.data)\n    let t0 = EVM.decodeABI(types: [Type<EVM.EVMAddress>()], data: t.data)[0] as! EVM.EVMAddress\n    return t0.toString() == a.toString() ? [rs[0] as! UInt256, rs[1] as! UInt256] : [rs[1] as! UInt256, rs[0] as! UInt256]\n}\n\naccess(all) fun main(user: Address?, amount: UFix64, router: String, factory: String, paths: [[String]], viaFlow: [Bool]): {String: AnyStruct} {\n    let out: {String: AnyStruct} = {}\n    let rt = EVM.addressFromString(router)\n    let fac = EVM.addressFromString(factory)\n    let dustEvm = FlowEVMBridgeConfig.getEVMAddressAssociated(with: Type<@FlovatarDustToken.Vault>())\n    let wflow = FlowEVMBridgeConfig.getEVMAddressAssociated(with: Type<@FlowToken.Vault>())\n    out[\"dustEvm\"] = dustEvm?.toString()\n    out[\"wflow\"] = wflow?.toString()\n    let flowKey = SwapConfig.SliceTokenTypeIdentifierFromVaultType(vaultTypeIdentifier: Type<@FlowToken.Vault>().identifier)\n    let dustKey = SwapConfig.SliceTokenTypeIdentifierFromVaultType(vaultTypeIdentifier: Type<@FlovatarDustToken.Vault>().identifier)\n    var flowNeeded: UFix64 = 0.0\n    if let pairAddr = SwapFactory.getPairAddress(token0Key: dustKey, token1Key: flowKey) {\n        let info = getAccount(pairAddr).capabilities.borrow<&{SwapInterfaces.PairPublic}>(SwapConfig.PairPublicPath)!.getPairInfo()\n        let dustFirst = (info[0] as! String) == dustKey\n        out[\"incrementPair\"] = pairAddr.toString()\n        out[\"incReserveDust\"] = dustFirst ? info[2] : info[3]\n        out[\"incReserveFlow\"] = dustFirst ? info[3] : info[2]\n        if amount > 0.0 {\n            flowNeeded = SwapRouter.getAmountsIn(amountOut: amount, tokenKeyPath: [flowKey, dustKey])[0]\n        }\n    }\n    out[\"flowNeeded\"] = flowNeeded\n\n    // wallet\n    var coa: EVM.EVMAddress? = nil\n    if let u = user {\n        let acct = getAccount(u)\n        out[\"flowAvailable\"] = acct.availableBalance\n        out[\"dustBalance\"] = acct.capabilities.borrow<&{FungibleToken.Balance}>(FlovatarDustToken.VaultBalancePath)?.balance ?? 0.0\n        if let c = acct.capabilities.borrow<&EVM.CadenceOwnedAccount>(/public/evm) {\n            coa = c.address()\n        } else if let c = getAuthAccount<auth(BorrowValue) &Account>(u).storage.borrow<&EVM.CadenceOwnedAccount>(from: /storage/evm) {\n            coa = c.address()\n        }\n    }\n    out[\"coa\"] = coa?.toString()\n    if coa != nil && paths.length > 0 && paths[0].length > 0 {\n        let b = dry(EVM.addressFromString(paths[0][0]), \"balanceOf(address)\", [coa!])\n        out[\"tokenInBalance\"] = b.status == EVM.Status.successful ? EVM.decodeABI(types: [Type<UInt256>()], data: b.data)[0] as! UInt256 : UInt256(0)\n        if let d = dustEvm {\n            let db = dry(d, \"balanceOf(address)\", [coa!])\n            out[\"coaDustWei\"] = db.status == EVM.Status.successful ? EVM.decodeABI(types: [Type<UInt256>()], data: db.data)[0] as! UInt256 : UInt256(0)\n        }\n    }\n\n    let routes: [{String: AnyStruct}] = []\n    var i = 0\n    while i < paths.length {\n        let r: {String: AnyStruct} = {\"path\": paths[i], \"viaFlow\": viaFlow[i], \"ok\": false, \"error\": \"\"}\n        let evmPath: [EVM.EVMAddress] = []\n        for p in paths[i] { evmPath.append(EVM.addressFromString(p)) }\n        let hops: [[UInt256]] = []\n        var j = 0\n        while j + 1 < evmPath.length { hops.append(hopReserves(fac, evmPath[j], evmPath[j + 1])); j = j + 1 }\n        r[\"hops\"] = hops\n        var outWei: UInt256 = 0\n        if viaFlow[i] {\n            r[\"flowNeeded\"] = flowNeeded\n            outWei = FlowEVMBridgeUtils.ufix64ToUInt256(value: flowNeeded, decimals: 18)\n        } else {\n            outWei = FlowEVMBridgeUtils.ufix64ToUInt256(value: amount, decimals: 18)\n        }\n        if amount > 0.0 && outWei > 0 {\n            let q = dry(rt, \"getAmountsIn(uint256,address[])\", [outWei, evmPath])\n            if q.status == EVM.Status.successful {\n                let amts = EVM.decodeABI(types: [Type<[UInt256]>()], data: q.data)[0] as! [UInt256]\n                r[\"amountIn\"] = amts[0]\n                r[\"ok\"] = true\n            } else {\n                r[\"error\"] = q.errorMessage\n            }\n        }\n        routes.append(r)\n        i = i + 1\n    }\n    out[\"routes\"] = routes\n    return out\n}\n";
